    # Full, uniform rows and columns are repeating-pattern separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(n, separators):
        out, start = [], 0
        for p in separators:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rs = segments(h, sep_rows)
    cs = segments(w, sep_cols)
    if len(rs) <= 1 and len(cs) <= 1:
