def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def parts(n, seps):
        result, start = [], 0
        for s in seps:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = parts(h, sep_rows), parts(w, sep_cols)
    tiles = [(a, b, c, d) for a, b in rows for c, d in cols]

    def score(t):
        a, b, c, d = t
        vals = [grid[r][col] for r in range(a, b) for col in range(c, d)]
        return sum(v != background for v in vals), len(set(vals))

    sr0, sr1, sc0, sc1 = max(tiles, key=score)
    th, tw = sr1 - sr0, sc1 - sc0
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r-r0) % th][sc0 + (c-c0) % tw]
    return out
